CREATE TABLE ref_cache(endpoint TEXT PRIMARY KEY, fetched_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE ref_commodities(id INTEGER PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL, available_live INTEGER NOT NULL);
CREATE INDEX ref_commodities_name ON ref_commodities(name);
CREATE INDEX ref_commodities_code ON ref_commodities(code);
PRAGMA user_version=1;
CREATE TABLE ref_terminals(id INTEGER PRIMARY KEY,name TEXT NOT NULL,nickname TEXT NOT NULL,display_name TEXT NOT NULL,location TEXT NOT NULL,available_live INTEGER NOT NULL,max_container_size INTEGER CHECK(max_container_size IS NULL OR max_container_size>0)); CREATE INDEX ref_terminals_name ON ref_terminals(name); CREATE INDEX ref_terminals_nickname ON ref_terminals(nickname); CREATE INDEX ref_terminals_display_name ON ref_terminals(display_name); CREATE INDEX ref_terminals_location ON ref_terminals(location);
CREATE TABLE reports(id INTEGER PRIMARY KEY AUTOINCREMENT,version INTEGER NOT NULL CHECK(version>=0),payload TEXT NOT NULL); CREATE TABLE report_recents(report_id INTEGER PRIMARY KEY REFERENCES reports(id),changed_order INTEGER NOT NULL); PRAGMA user_version=3;
CREATE TABLE screenshot_requirements(account_digest BLOB PRIMARY KEY CHECK(length(account_digest)=32),observed_at TEXT NOT NULL); PRAGMA user_version=6;
ALTER TABLE reports ADD COLUMN phase TEXT NOT NULL DEFAULT 'draft'; CREATE TABLE submission_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,report_id INTEGER NOT NULL REFERENCES reports(id),revision INTEGER NOT NULL CHECK(revision>0),phase TEXT NOT NULL,payload TEXT NOT NULL,release_report TEXT NOT NULL,release_report_version INTEGER NOT NULL CHECK(release_report_version>0)); CREATE UNIQUE INDEX submission_one_sending ON submission_jobs((1)) WHERE phase='sending'; CREATE TABLE domain_outbox(event_source TEXT NOT NULL,aggregate_id INTEGER NOT NULL,revision INTEGER NOT NULL,event_kind TEXT NOT NULL,delivered INTEGER NOT NULL DEFAULT 0 CHECK(delivered IN(0,1)),PRIMARY KEY(event_source,aggregate_id,revision)); CREATE TABLE accepted_priors(sequence INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL REFERENCES submission_jobs(id),commodity INTEGER NOT NULL,environment TEXT NOT NULL,projection TEXT NOT NULL,payload TEXT NOT NULL,UNIQUE(submission_id,commodity)); CREATE INDEX accepted_priors_projection ON accepted_priors(environment,projection); CREATE TABLE submission_receipt_enrichment(job_id INTEGER PRIMARY KEY REFERENCES submission_jobs(id),job_revision INTEGER NOT NULL CHECK(job_revision>0),payload TEXT); PRAGMA user_version=9;
